/* R23: single, page-agnostic OpenDesk semantic tokens.
 * No resets, selectors for host pages, remote resources or page scroll policy.
 * Trusted extension UI only; never inject into tools, iframes or web pages. */
:root{
  --od-ink:#1b2c49;
  --od-sub:#5b6e86;
  --od-line:#dfe6ef;
  --od-brand:#365eda;
  --od-paper:#fff;
  --od-bg:#fff;
  --od-input-border:#7f8da1;
  --od-accent-ink:var(--od-brand);
  --od-focus:var(--od-brand);
  --od-light-warning:#80510d;
  --od-warning:var(--od-light-warning);
  --od-muted:#f5f7fb;
  --od-light-positive:#117a5d;
  --od-positive:var(--od-light-positive);
  --od-negative:#ae3d4b;
  --space-1:4px;
  --space-2:8px;
  --space-3:12px;
  --space-4:16px;
  --radius-control:8px;
  --radius-surface:12px;
  --radius-pill:999px;
  --od-icon-size:34px;
  --od-body-size:13px;
  --od-note-size:12px;
  --od-meta-size:11px;
  --od-on-brand:#fff;
  --od-action-bg:var(--od-muted);
  --od-action-border:var(--od-input-border);
  --od-action-ink:var(--od-ink);
  --od-light-warning-bg:#fff9ec;
  --od-light-warning-border:#dcc58a;
  --od-light-warning-ink:#76501b;
  --od-warning-bg:var(--od-light-warning-bg);
  --od-warning-border:var(--od-light-warning-border);
  --od-warning-ink:var(--od-light-warning-ink);
  --od-negative-bg:#fff0f1;
  /* Host horizontal inset, used once; sandbox tool content owns its own inner inset. */
  --od-page-gutter:12px;
  /* Dark-mode palette is registered here; shared primitives only reference tokens. */
  --od-dark-ink:#e9eef7;
  --od-dark-sub:#b3c1d3;
  --od-dark-line:#374457;
  --od-dark-brand:#3566ba;
  --od-dark-paper:#151c28;
  --od-dark-bg:#101722;
  --od-dark-input-border:#6d809b;
  --od-dark-accent-ink:#9dc1ff;
  --od-dark-warning:#ffd08a;
  --od-dark-warning-bg:#392d21;
  --od-dark-warning-border:#8b6841;
  --od-dark-warning-ink:#f6dca8;
  --od-dark-muted:#222d3e;
  --od-dark-positive:#a1f3cc;
  --od-dark-negative:#ff9ea6;
  /* Existing Sidebar aliases; do not redeclare palette values per page. */
  --ink:var(--od-ink);
  --sub:var(--od-sub);
  --line:var(--od-line);
  --blue:var(--od-brand);
  --paper:var(--od-paper);
}

/* Dark palette stays with the canonical tokens; design-system.css owns layout only. */
@media(prefers-color-scheme:dark){
  :root{
    --od-ink:var(--od-dark-ink);
    --od-sub:var(--od-dark-sub);
    --od-line:var(--od-dark-line);
    --od-brand:var(--od-dark-brand);
    --od-paper:var(--od-dark-paper);
    --od-bg:var(--od-dark-bg);
    --od-input-border:var(--od-dark-input-border);
    --od-accent-ink:var(--od-dark-accent-ink);
    --od-focus:var(--od-dark-accent-ink);
    --od-warning:var(--od-dark-warning);
    --od-muted:var(--od-dark-muted);
    --od-positive:var(--od-dark-positive);
    --od-negative:var(--od-dark-negative);
    --od-warning-bg:var(--od-dark-warning-bg);
    --od-warning-border:var(--od-dark-warning-border);
    --od-warning-ink:var(--od-dark-warning-ink);
