body{margin:0;background:var(--od-bg)}
.fc-panel{color:var(--od-ink);font:13px/1.5 -apple-system,BlinkMacSystemFont,"PingFang SC",system-ui,sans-serif;padding:16px 12px;min-width:0}
.fc-panel *{box-sizing:border-box}.fc-panel [hidden]{display:none!important}
.fc-setting{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:48px}
.fc-setting-copy{min-width:0}.fc-setting-copy label{display:block;font-size:13px;font-weight:650}
.fc-note{font-size:12px;line-height:1.55;color:var(--od-sub);margin:4px 0 0;overflow-wrap:anywhere}
.fc-switch{appearance:none;-webkit-appearance:none;flex:none;position:relative;width:38px;height:36px;margin:0;border:0;background:transparent;cursor:pointer}
.fc-switch:before{content:"";position:absolute;inset:7px 0;width:38px;height:22px;border-radius:999px;background:var(--od-input-border);transition:background .12s ease}
.fc-switch:after{content:"";position:absolute;top:9px;left:2px;width:18px;height:18px;border-radius:50%;background:var(--od-on-brand);transition:transform .12s ease}
.fc-switch:checked:before{background:var(--od-brand)}
.fc-switch:checked:after{transform:translateX(16px)}
.fc-switch:disabled{opacity:.52;cursor:not-allowed}
.fc-switch:focus-visible{outline:2px solid var(--od-brand);outline-offset:3px}
.fc-divider{border-top:1px solid var(--od-line);margin:15px 0}
.fc-status{margin:15px 0 0;color:var(--od-accent-ink);font-size:12px;font-weight:600}
.fc-hint{margin:9px 0 0;color:var(--od-sub);font-size:12px;line-height:1.6}
.fc-error{margin:12px 0 0;color:var(--od-negative);font-size:12px}
@media(prefers-reduced-motion:reduce){.fc-switch:before,.fc-switch:after{transition:none}}

